#include "tileStorage.h"

#include <QDebug>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QStringList>
#include <stdexcept>

TileStorage::TileStorage(const QString &jsonFilePath, const QString &parseType)
{
    if (parseType == "allTiles")
    {
        parseAllTilesFromJson(jsonFilePath);
    }
    else
    {
        parseStartingTilesFromJson(jsonFilePath);
    }
}

TileStorage::~TileStorage() = default;

void TileStorage::parseAllTilesFromJson(const QString &jsonFilePath)
{
    QFile file(jsonFilePath);

    if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
    {
        throw std::runtime_error("Error: Could not open JSON file!");
    }

    QJsonDocument doc = QJsonDocument::fromJson(file.readAll());
    file.close();

    if (!doc.isObject())
    {
        throw std::runtime_error("Error: JSON file format is invalid!");
    }

    QJsonObject root = doc.object();

    QJsonArray allTilesArray = root.value("allTiles").toArray();
    for (const QJsonValue &tileValue : allTilesArray)
    {
        QJsonObject tileObj    = tileValue.toObject();
        int         tileNumber = tileObj.value("tileNum").toString().toInt();

        QStringList      habitatsList = tileObj.value("habitats").toVariant().toStringList();
        QVector<QString> habitats;
        for (const QString &habitat : habitatsList)
        {
            habitats.push_back(habitat);
        }

        QStringList      wildlifeList = tileObj.value("wildlife").toVariant().toStringList();
        QVector<QString> wildlife;
        for (const QString &animal : wildlifeList)
        {
            wildlife.push_back(animal);
        }

        int rotation = tileObj.value("rotation").toInt();

        Tile tile(tileNumber, habitats, wildlife, rotation);
        m_allTiles.push_back(tile);
    }
}

void TileStorage::parseStartingTilesFromJson(const QString &jsonFilePath)
{
    QFile file(jsonFilePath);

    if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
    {
        throw std::runtime_error("Error: Could not open JSON file!");
    }

    QJsonDocument doc = QJsonDocument::fromJson(file.readAll());
    file.close();

    if (!doc.isObject())
    {
        throw std::runtime_error("Error: JSON file format is invalid!");
    }

    QJsonObject root = doc.object();

    QJsonArray startingTilesArray = root.value("startingTiles").toArray();
    for (const QJsonValue &rowValue : startingTilesArray)
    {
        QVector<Tile> row;
        QJsonArray    rowArray = rowValue.toArray();
        for (const QJsonValue &tileValue : rowArray)
        {
            QJsonObject tileObj    = tileValue.toObject();
            int         tileNumber = tileObj.value("tileNum").toString().toInt();

            QStringList      habitatsList = tileObj.value("habitats").toVariant().toStringList();
            QVector<QString> habitats;
            for (const QString &habitat : habitatsList)
            {
                habitats.push_back(habitat);
            }

            QStringList      wildlifeList = tileObj.value("wildlife").toVariant().toStringList();
            QVector<QString> wildlife;
            for (const QString &animal : wildlifeList)
            {
                wildlife.push_back(animal);
            }

            int rotation = tileObj.value("rotation").toInt();

            Tile tile(tileNumber, habitats, wildlife, rotation);
            row.push_back(tile);
        }
        m_startingTiles.push_back(row);
    }
}

auto TileStorage::allTiles() const -> const QVector<Tile> &
{
    return m_allTiles;
}

auto TileStorage::startingTiles() const -> const QVector<QVector<Tile>> &
{
    return m_startingTiles;
}
